const __pageData = JSON.parse('{"title":"13. Labelling, QR codes and battery passports","description":"","frontmatter":{},"headers":[],"relativePath":"13-labelling-and-qr-codes.md","filePath":"13-labelling-and-qr-codes.md"}');
